// A field of the input: the designer sends it in the input JSON,
// a published plugin fills it from the request header.
string requestId = Input.x_ms_client_request_id;
if (string.IsNullOrEmpty(requestId))   // a start that sends only the header
    requestId = ServiceProvider.GetService<HttpRequestService>()?.Request?.Headers?
        .FirstOrDefault(h => string.Equals(h.Key, "x-ms-client-request-id", StringComparison.OrdinalIgnoreCase)).Value;
if (string.IsNullOrEmpty(requestId))
    throw new Exception("x-ms-client-request-id is required");
Parameters.cacheKey = $"idempotent-request:{requestId}";
return requestId;

var cache = ServiceProvider.GetService<IDistributedCache>()
    ?? throw new Exception("the distributed cache is not available");
var stored = cache.GetString(Parameters.cacheKey);
if (stored == "pending")
    throw new Exception("the same request is in progress");
if (stored == null)       // taken: a parallel retry gets 409 while the work runs
{
    cache.SetString(Parameters.cacheKey, "pending",
        new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(60) });
    return null;
}
return JsonConvert.DeserializeObject(stored);   // a damaged entry fails here

// The stored answer, unchanged: a client that lost the response can retry safely.
var answer = new JSON(#Previous).Cast<PaymentAnswer>();
answer.cacheStatus = "IsCompleted";
WorkflowEnvironment.Variables["StatusCode"] = 201;
if (WorkflowEnvironment.Variables.TryGetValue("HttpResponse", out object raw)
    && raw is Microsoft.AspNetCore.Http.HttpResponse response)
    response.Headers["cacheStatus"] = answer.cacheStatus;
return answer;

// The work itself, done once per request id: here it only issues a
// confirmation, so a repeated call is easy to recognise.
return new PaymentAnswer()
{
    orderId = Input.orderId,
    amount = Input.amount,
    confirmation = Guid.NewGuid().ToString(),
    acceptedAt = DateTime.UtcNow.ToString("o"),
    cacheStatus = "Added"
};

// After the work: a failure to store is logged, the answer still goes back.
var answer = #Previous;      // stored as it is: the type is not needed here
var seconds = Parameters.config.cacheSeconds > 0 ? Parameters.config.cacheSeconds : 300;
try
{
    ServiceProvider.GetService<IDistributedCache>().SetString(Parameters.cacheKey,
        JsonConvert.SerializeObject(answer),
        new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(seconds) });
}
catch (Exception e) { Logger.LogError($"the answer was not stored: {e.Message}"); }
return answer;

// 201: the request created something. cacheStatus is a response header;
// the answer repeats it so a start through the API shows it too.
var answer = (PaymentAnswer)#Previous;
WorkflowEnvironment.Variables["StatusCode"] = 201;
if (WorkflowEnvironment.Variables.TryGetValue("HttpResponse", out object raw)
    && raw is Microsoft.AspNetCore.Http.HttpResponse response)
    response.Headers["cacheStatus"] = answer.cacheStatus;
return answer;

types.PaymentAnswer:
public class PaymentAnswer
{
    public string orderId { get; set; }
    public double amount { get; set; }
    /* Issued once per request id: a repeated call gets the same value. */
    public string confirmation { get; set; }
    public string acceptedAt { get; set; }
    /* The cacheStatus response header, repeated in the answer: Added or IsCompleted. */
    public string cacheStatus { get; set; }
}
